/**
 * Display helpers for GraphQL HTTP request bodies (query / variables / operationName).
 * Prefer this over JSON.stringify so the query is copyable with real newlines.
 */
export interface GraphqlRequestBodyFields {
    query: string;
    variables?: unknown;
    operationName?: string;
    extensions?: unknown;
}
/** True when value looks like a standard GraphQL POST JSON body. */
export declare function isGraphqlRequestBodyObject(value: unknown): value is GraphqlRequestBodyFields;
/**
 * True when text was already formatted by {@link formatGraphqlRequestBodyObject}
 * (or starts with a GraphQL operation document).
 */
export declare function looksLikeGraphqlDisplayText(text: string): boolean;
/**
 * GraphQL operation name from a request body preview: wire JSON, display form
 * (`# operationName: X`), or a truncated preview that no longer parses. Falls
 * back to the name in the query document. Empty string when there is none.
 *
 * Self-contained on purpose: the Atlas live page embeds this function's source.
 */
export declare function graphqlOperationNameFromBodyText(text: string | null | undefined): string;
/** Soft-indent a single-line GraphQL document for display (brace-based only). */
export declare function softIndentGraphqlQuery(query: string): string;
/** Normalize a GraphQL query string for readable display (real newlines, light indent). */
export declare function formatGraphqlQueryForDisplay(query: string): string;
/** Format a parsed GraphQL request body for copy/paste display. */
export declare function formatGraphqlRequestBodyObject(body: GraphqlRequestBodyFields): string;
/**
 * If `text` is a GraphQL request JSON body, return a readable multi-line display string.
 * Otherwise return null.
 */
export declare function tryFormatGraphqlRequestBodyText(text: string): string | null;
/**
 * Prefer GraphQL-aware display; otherwise return null so callers can fall back to JSON pretty.
 */
export declare function formatBodyPreviewForDisplay(text: string): string;
/**
 * Reverse {@link formatGraphqlRequestBodyObject} back to a wire-safe GraphQL HTTP JSON body.
 * Used when Atlas curl / include-trace accidentally hold the display form instead of JSON.
 */
export declare function tryGraphqlDisplayTextToRequestJson(text: string): string | null;
